  {% set geschmack = (s | lower).startswith('nach geschmack') %}
  {% set m = s | regex_findall('^([\d.,/½¼¾]+(?:\s*-\s*[\d.,/½¼¾]+)?)\s*(?:(' ~ units ~ ')\s+)?(.+)$') %}
  {% set n = (m[0][0].split('-') | last | trim) if m else '' %}
  {% set u = (einheit.get(m[0][1], m[0][1]) or 'Stück') if m else '' %}
  {% set name = (m[0][2] if m else s) | trim(' ,.') %}
  {% set n = n | replace(',', '.') | replace('½', '0.5') | replace('¼', '0.25') | replace('¾', '0.75') %}
  {% if '/' in n %}
    {% set p = n.split('/') %}
    {% set q = (p[0] | float(0)) / ([p[1] | float(1), 1] | max) %}
  {% else %}
    {% set q = n | float(0) %}
  {% endif %}
  {# Kräuterpacks wie 'Petersilie glatt/Rosmarin' in Einzelartikel ohne Menge aufteilen #}
  {% set teile = name.split('/') %}
  {% for teil in teile %}
    {% set tname = teil | trim %}
    {% set tu = u if teile | length == 1 else '' %}
    {% set tq = q if teile | length == 1 else 0 %}
    {% set key = tname | lower %}
    {# Allgemeine Regeln: Zusaetze wie mittelgross, frisch, Bio, kl. Dose streichen, Farben und Sorten vereinheitlichen #}
