      {% set tname = tname
        | regex_replace('^(?:kleine|große|mittelgroße)[rsn]? (?:oder|bis) ', '', ignorecase=True)
        | regex_replace('^(.+?), ?(rot|gelb|grün|weiß)(?:e[rsn]?)?(?=$|[ ,]).*$', '\\2e \\1', ignorecase=True)
        | regex_replace('^(.*(?:käse|gouda|parmesan|cheddar|mozzarella|emmentaler|pecorino|grana).*?), ?(?:frisch )?(?:und )?(?:fein )?(gerieben|gehobelt)(?=$|[ ,]).*$', '\\1 \\2', ignorecase=True)
