        | regex_replace('^(?:bio[- ]|frische[rsn]? |reife[rsn]? |essreife[rsn]? |kleine[rsn]? |große[rsn]? |mittelgroße[rsn]? |unbehandelte[rsn]? |gehackte[rsn]? |junge[rsn]? |würzige[rsn]? |kl\\. |gr\\. |kleines stück |guter spritzer |spritzer |dosen? |gläser |glas |stängel |topf |bund |eßlöffel |₂ |g |gr |circa |ca\\. ?[0-9]+ ?g )', '', ignorecase=True)
        | regex_replace('^(?:bio[- ]|frische[rsn]? |reife[rsn]? |essreife[rsn]? |kleine[rsn]? |große[rsn]? |mittelgroße[rsn]? |unbehandelte[rsn]? |gehackte[rsn]? |junge[rsn]? |würzige[rsn]? |kl\\. |gr\\. |kleines stück |guter spritzer |spritzer |dosen? |gläser |glas |stängel |topf |bund |eßlöffel |₂ |g |gr |circa |ca\\. ?[0-9]+ ?g )', '', ignorecase=True)
        | regex_replace('^(?:bio[- ]|frische[rsn]? |reife[rsn]? |essreife[rsn]? |kleine[rsn]? |große[rsn]? |mittelgroße[rsn]? |unbehandelte[rsn]? |gehackte[rsn]? |junge[rsn]? |würzige[rsn]? |kl\\. |gr\\. |kleines stück |guter spritzer |spritzer |dosen? |gläser |glas |stängel |topf |bund |eßlöffel |₂ |g |gr |circa |ca\\. ?[0-9]+ ?g )', '', ignorecase=True)
        | regex_replace('^passierte[rsn]? (.+)$', '\\1 passiert', ignorecase=True)
        | regex_replace('^stückige[rsn]? (.+)$', '\\1 stückig', ignorecase=True)
        | regex_replace('^getrocknete[rsn]? (.+)$', '\\1 getrocknet', ignorecase=True)
        | regex_replace('^geräucherte[rsn]? (.+)$', '\\1 geräuchert', ignorecase=True)
        | regex_replace('^gesalzene[rsn]? (.+)$', '\\1 gesalzen', ignorecase=True)
        | regex_replace('^geriebene[rsn]? (.*(?:käse|gouda|parmesan|cheddar|mozzarella|emmentaler|pecorino|grana).*)$', '\\1 gerieben', ignorecase=True)
        | regex_replace('^geriebene[rsn]? ', '', ignorecase=True)
        | regex_replace('^vorw\\.? ?festk[a-zäö.]* (.+)$', '\\1 vorwiegend festkochend', ignorecase=True)
        | regex_replace('^mehligk[a-zäö.]* (.+)$', '\\1 mehlig kochend', ignorecase=True)
        | regex_replace(' mehligkochend$', ' mehlig kochend', ignorecase=True)
        | regex_replace(' (?:à |je )?ca\\. .*$', '', ignorecase=True)
        | regex_replace(' (?:oder|bzw\\.) .*$', '', ignorecase=True)
        | regex_replace(' aus dem glas$', '', ignorecase=True)
        | regex_replace(' à [0-9].*$', '', ignorecase=True)
        | regex_replace('[ ,.!]+$', '', ignorecase=True)
        | trim %}
