    {# Flüssiges eins zu eins von Gramm in Milliliter, Knoblauch immer in Zehen: so addieren sich die Mengen #}
    {% if tu == 'Gramm' and key in ['sahne', 'milch', 'kokosmilch', 'buttermilch', 'brühe', 'gemüsebrühe', 'hühnerbrühe', 'rinderbrühe', 'weißwein', 'rotwein'] %}{% set tu = 'Milliliter' %}{% endif %}
