    {% endif %}
  {% endfor %}
{% endfor %} {{ ns.e }}

variables.plan:
{% set ns = namespace(neu=[], aendern=[], weg=[]) %} {% set liste = eintraege | rejectattr('vorrat') | list %} {% for key in liste | map(attribute='key') | unique %}
  {% set gruppe = liste | selectattr('key', 'eq', key) | list %}
  {% set t = namespace(p=[]) %}
  {% for u in gruppe | map(attribute='unit') | unique %}
    {% set q = gruppe | selectattr('unit', 'eq', u) | map(attribute='qty') | sum %}
    {% if q > 0 %}
      {% set qr = q | round(2) %}
      {% set qs = (qr | int) if qr == (qr | int) else qr %}
      {% set t.p = t.p + [((qs | string | replace('.', ',')) ~ ' ' ~ u) | trim] %}
    {% endif %}
  {% endfor %}
  {% set menge = t.p | join(' + ') %}
  {% set b = namespace(uid='', desc='') %}
  {% for x in bring %}
    {% if (x.summary | lower | trim) == key %}
      {% set b.uid = x.uid %}
      {% set b.desc = x.description | default('', true) %}
    {% endif %}
  {% endfor %}
  {# Eigene Notiz auf Bring! behalten: der Rezeptanteil steht hinter einem unsichtbaren Trennzeichen (U+200B) #}
  {% set zw = '​' %}
  {% set basis = (b.desc.split(zw)[0].rstrip(' +')) if zw in b.desc else (b.desc | trim) %}
  {% set neu_desc = ((basis ~ ' + ') if basis and menge else basis) ~ ((zw ~ menge) if menge else '') %}
  {% if not b.uid %}
    {% set ns.neu = ns.neu + [{'name': gruppe[0].name, 'menge': (zw ~ menge) if menge else ''}] %}
  {% elif menge and b.desc != neu_desc %}
    {% set ns.aendern = ns.aendern + [{'uid': b.uid, 'menge': neu_desc}] %}
  {% endif %}
{% endfor %} {# Rezeptanteil wieder entfernen, wenn der Artikel nicht mehr auf der Mealie-Liste steht #}
{% set zw = '​' %}
{% set keys = liste | map(attribute='key') | list %}
{% for x in bring %}
  {% set xd = x.description | default('', true) %}
  {% if zw in xd and (x.summary | lower | trim) not in keys %}
    {% set basis = xd.split(zw)[0].rstrip(' +') %}
    {% if basis %}
      {% set ns.aendern = ns.aendern + [{'uid': x.uid, 'menge': basis}] %}
    {% else %}
      {% set ns.weg = ns.weg + [x.uid] %}
    {% endif %}
  {% endif %}
{% endfor %} {{ {'neu': ns.neu, 'aendern': ns.aendern, 'weg': ns.weg} }}

